/**
 * Readable aliases over the generated contract types. Import domain shapes from here
 * rather than reaching into `schema.d.ts`, which is regenerated by `npm run gen:api`.
 */
import type { components, operations } from './schema';

type Schemas = components['schemas'];

export type Problem = Schemas['Problem'];
export type Severity = Schemas['Severity'];
export type Category = Schemas['Category'];
export type CheckStatus = Schemas['CheckStatus'];
export type HostStatus = Schemas['HostStatus'];
export type DriftDirection = Schemas['DriftDirection'];

export type OsInfo = Schemas['OsInfo'];
export type StatusCounts = Schemas['StatusCounts'];
export type CheckResult = Schemas['CheckResult'];
export type ScanSummary = Schemas['ScanSummary'];
export type ScanDetail = Schemas['ScanDetail'];
export type Host = Schemas['Host'];
export type HostPage = Schemas['HostPage'];

export type CheckFailure = Schemas['CheckFailure'];
export type FleetSummary = Schemas['FleetSummary'];
export type FleetTrend = Schemas['FleetTrend'];
export type FleetTrendPoint = Schemas['FleetTrendPoint'];

export type CheckSummary = Schemas['CheckSummary'];
export type CheckDetail = Schemas['CheckDetail'];
export type CheckHostStatus = Schemas['CheckHostStatus'];

export type DriftChange = Schemas['DriftChange'];
export type DriftReport = Schemas['DriftReport'];
export type DriftEvent = Schemas['DriftEvent'];

export type HostListQuery = NonNullable<operations['listHosts']['parameters']['query']>;
export type HostSortField = NonNullable<HostListQuery['sort']>;
export type SortDirection = NonNullable<HostListQuery['direction']>;
export type FleetTrendQuery = NonNullable<operations['getFleetTrend']['parameters']['query']>;
export type DriftEventQuery = NonNullable<operations['listDriftEvents']['parameters']['query']>;
